function unpackBrain(encoded){
 const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),header=new Uint32Array(bytes.buffer,0,4);let offset=16;
 function read(count,columns,signed,scale=1){const array=signed?new Int16Array(bytes.buffer,offset,count*columns):new Uint16Array(bytes.buffer,offset,count*columns);offset+=count*columns*2;return Array.from({length:count},(_,i)=>Array.from(array.subarray(i*columns,(i+1)*columns),n=>n/scale))}
 const v=read(header[0],3,true,10000),f=read(header[1],3,false),p=read(header[2],4,true,10000),n=read(header[3],2,false),edges=new Map();
 f.forEach((face,i)=>{for(let j=0;j<3;j++){const x=face[j],y=face[(j+1)%3],a=Math.min(x,y),b=Math.max(x,y),key=a+':'+b;if(edges.has(key))edges.get(key)[3]=i;else edges.set(key,[a,b,i,-1])}});
 return {v,f,p,n,e:[...edges.values()]};
}

const outlineBrainData=unpackBrain("");
function startOutlineBrain(root,model,options={}){
 const canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d'),button=root.querySelector('button');
 let externalVisible=true;let width=600,height=480,ratio=1,yaw=1.28,pitch=-.27,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,last=0,visible=true,dragging=false,pointer;
 const normals=model.f.map(([a,b,c])=>{const p=model.v[a],q=model.v[b],r=model.v[c],u=q.map((x,i)=>x-p[i]),v=r.map((x,i)=>x-p[i]);const n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],length=Math.hypot(...n)||1;return n.map(x=>x/length)});
 function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;ratio=Math.min(devicePixelRatio||1,1.5);canvas.width=width*ratio;canvas.height=height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0)}
 new ResizeObserver(resize).observe(canvas);resize();
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting});observer.observe(root);
 function controls(){button.textContent=paused?'Play rotation':'Pause rotation';button.setAttribute('aria-pressed',String(paused));root.dataset.motion=paused?'paused':'running'}controls();button.onclick=()=>{paused=!paused;controls()};
 canvas.onpointerdown=e=>{if(e.pointerType!=='mouse')return;dragging=true;pointer=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=canvas.onpointercancel=()=>{dragging=false};canvas.onpointermove=e=>{if(dragging){yaw+=(e.clientX-pointer[0])*.007;pitch=Math.max(-1.1,Math.min(1.1,pitch+(e.clientY-pointer[1])*.007));pointer=[e.clientX,e.clientY]}};
 function draw(){
  if(options.bridge)parent.postMessage({type:"brain-pose",yaw,pitch},location.origin);
  const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),scale=Math.min(width*(options.bridge?.23:.31),height*(options.bridge?.25:.31));
  function rotate([x,y,z]){const a=x*cy+z*sy,b=-x*sy+z*cy;return [a,y*cp-b*sp,y*sp+b*cp]}
  function project(v){const p=rotate(v),s=scale*5/(5+p[2]);return [width*.5+p[0]*s,height*.39-p[1]*s,p[2]]}
  const p=model.v.map(project),n=normals.map(rotate),dots=model.p.map(project),front=n.map(v=>v[2]<0);
  ctx.clearRect(0,0,width,height);ctx.fillStyle='#000';ctx.fillRect(0,0,width,height);
  // A translucent anatomical surface supplies form without sealing the interior.
  for(let tone=0;tone<8;tone++){
   ctx.beginPath();for(let i=0;i<model.f.length;i++){if(!front[i])continue;const normal=n[i],light=Math.max(0,normal[0]*-.4+normal[1]*.6-normal[2]*.7);if(Math.min(7,Math.floor(light*7))!==tone)continue;const [a,b,c]=model.f[i];ctx.moveTo(p[a][0],p[a][1]);ctx.lineTo(p[b][0],p[b][1]);ctx.lineTo(p[c][0],p[c][1]);ctx.closePath()}
   ctx.fillStyle=`rgba(${50+tone*5},${75+tone*13},255,${.04+tone*.009})`;ctx.fill();
  }
  // Interior connections stay sparse and visible through the cortical shell.
  ctx.beginPath();for(const [a,b] of model.n){if(width<480&&(a+b)%2)continue;ctx.moveTo(dots[a][0],dots[a][1]);ctx.lineTo(dots[b][0],dots[b][1])}ctx.strokeStyle='rgba(37,209,255,.12)';ctx.lineWidth=.6;ctx.stroke();
  // Smooth tangent contours pick out the cortex and its natural folded ridges.
  const adjacency=new Map(),contourEdges=[];
  for(const [a,b,x,y] of model.e){if(y>=0&&front[x]===front[y])continue;contourEdges.push([a,b]);if(!adjacency.has(a))adjacency.set(a,[]);if(!adjacency.has(b))adjacency.set(b,[]);adjacency.get(a).push(b);adjacency.get(b).push(a)}
  const visited=new Set(),paths=[];const key=(a,b)=>a<b?a+':'+b:b+':'+a;
  for(const [start,next] of contourEdges){if(visited.has(key(start,next)))continue;const ids=[start];let previous=start,current=next;visited.add(key(start,next));
   for(let step=0;step<1500;step++){ids.push(current);const candidates=adjacency.get(current)||[];const following=candidates.find(i=>i!==previous&&!visited.has(key(current,i)));if(following===undefined)break;visited.add(key(current,following));previous=current;current=following;if(current===start){ids.push(start);break}}
   if(ids.length>5)paths.push(ids);
  }
  for(let glow=0;glow<2;glow++){
   ctx.beginPath();for(const ids of paths){const points=ids.map(i=>p[i]);let length=0;for(let i=1;i<points.length;i++)length+=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);if(length<9)continue;
    ctx.moveTo((points[0][0]+points[1][0])*.5,(points[0][1]+points[1][1])*.5);for(let i=1;i<points.length-1;i++)ctx.quadraticCurveTo(points[i][0],points[i][1],(points[i][0]+points[i+1][0])*.5,(points[i][1]+points[i+1][1])*.5);
   }
   ctx.strokeStyle=glow?'rgba(153,197,255,.43)':'rgba(85,119,255,.17)';ctx.lineWidth=glow?.7:2;ctx.shadowColor='#627dff';ctx.shadowBlur=glow?0:5;ctx.stroke();ctx.shadowBlur=0;
  }
  for(let i=0;i<model.p.length;i++){const isInside=model.p[i][3];if(width<480&&i%2)continue;const [x,y,z]=dots[i],near=Math.max(.1,Math.min(.7,.38-z*.12));ctx.fillStyle=isInside?`rgba(112,231,255,${near*.65})`:`rgba(162,209,255,${near*.6})`;ctx.beginPath();ctx.arc(x,y,isInside?.65:.55,0,Math.PI*2);ctx.fill()}
 }
 function frame(t){requestAnimationFrame(frame);if(t-last<50||!visible||!externalVisible||document.hidden)return;const dt=Math.min((t-last)/1000,.08);last=t;if(!paused&&!dragging)yaw+=dt*.23;draw()}
 if(options.bridge){addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin)return;if(e.data?.type==='brain-motion'){paused=!e.data.run;controls()}if(e.data?.type==='brain-visibility')externalVisible=Boolean(e.data.visible)});parent.postMessage({type:'brain-ready'},location.origin)}
 draw();requestAnimationFrame(frame);
 return {draw,setView:(angle,tilt=-.27)=>{yaw=angle;pitch=tilt;draw()},dispose:()=>observer.disconnect()};
}

startOutlineBrain(document.body,outlineBrainData,{bridge:true});
